let statsFocusedItem=null;

const descriptions={'Attack Range':'Bonus attack range. Melee/ranged restrictions and aura bonuses are marked beside the value.', 'Status Resist':'Reduces the duration of most negative status effects applied to the hero, such as stuns, roots, silences and slows. For example, 25% total status resistance reduces an affected 4-second debuff to 3 seconds, before other duration modifiers. It does not reduce the strength of a movement slow; that is Slow Resistance. Some effects ignore status resistance.', 'Slow Resist':'Reduces the strength of movement-speed slows, rather than how long they last. Status Resistance affects the duration of affected slows.',  Gold:'Gold — purchase cost of the item.',STR:'Strength — direct strength and all-attribute bonuses combined.',AGI:'Agility — direct agility and all-attribute bonuses combined.',INT:'Intelligence — direct intelligence and all-attribute bonuses combined.',HP:'HP — direct maximum health bonus. Does not include health from strength.',Mana:'Mana — direct maximum mana bonus.', 'Hp Regen':'Health regeneration per second. A % value is a percentage of maximum HP per second. Fixed and percentage values sort in separate groups; they cannot be compared without maximum HP.', 'Mana Regen':'Mana regeneration per second; percentage modifiers retain their % sign.',Armor:'Armor — direct armor bonus, excluding agility and auras.',Evasion:'Evasion — listed chance to evade attacks.','Magic Resist':'Magic resistance — direct listed bonus.', 'Spell Amp':'Spell amplification — listed percentage bonus to spell damage.',Damage:'Attack damage — direct bonus damage to attacks.', 'Attack Speed':'Attack speed — direct listed bonus.', 'Move speed':'Movement speed — direct listed bonus.',Type:'Item category from the supplied Liquipedia table. Unclassified means no matching category was found.'};
function componentKeys(key){const i=DATA[key];if(i?.recipeVariants?.length)return i.recipeVariants[0];if(!i||key.startsWith('recipe_'))return [];const list=(i.components||[]).filter(k=>k);const recipe='recipe_'+key;if(DATA[recipe]&&DATA[recipe].cost>0&&!list.includes(recipe))list.push(recipe);return list}
function recipeButton(key,count=1){const i=DATA[key];if(!i)return '<span class="recipe-missing">'+esc(key)+' — details unavailable</span>';return '<button type="button" class="recipe-item" data-recipe-item="'+esc(key)+'"><img alt="" loading="lazy" src="https://cdn.cloudflare.steamstatic.com'+esc(i.img)+'"><span>'+esc(i.dname)+(count>1?' ×'+count:'')+'<small>'+((i.cost||0)>0?Number(i.cost).toLocaleString()+' gold'+(count>1?' each':''):'No gold cost listed')+'</small></span></button>'}
function recipeBranch(key,path=[]){if(path.includes(key))return '<li>Recipe loop — not expanded</li>';const children=componentKeys(key);const counts=new Map();for(const c of children)counts.set(c,(counts.get(c)||0)+1);return [...counts].map(([c,count])=>'<li>'+recipeButton(c,count)+(componentKeys(c).length?'<details class="recipe-subtree"><summary>Components</summary><ul>'+recipeBranch(c,[...path,key])+'</ul></details>':'')+'</li>').join('')}
function recipeSection(key){const i=DATA[key],children=componentKeys(key);const upgrades=Object.keys(DATA).filter(k=>!k.startsWith('recipe_')&&(DATA[k].recipeVariants||[DATA[k].components||[]]).some(r=>r.includes(key)));const incomplete=(i.components||[]).some(k=>!k)&&!DATA['recipe_'+key];const total=children.reduce((sum,k)=>sum+(DATA[k]?.cost||0),0);const mismatch=children.length&&children.every(k=>DATA[k])&&i.cost>0&&total!==i.cost;return '<section class="item-recipe"><h3>BUILD RECIPE</h3>'+(children.length?'<ul class="recipe-tree">'+recipeBranch(key)+'</ul>'+(i.recipeVariants?.length>1?'<p class="recipe-note">Alternative recipes:</p>'+i.recipeVariants.slice(1).map(r=>'<div class="recipe-upgrades">'+r.map(k=>recipeButton(k)).join('')+'</div>').join(''):''):'<p class="recipe-note">'+(key.startsWith('recipe_')?'Recipe scroll — used to complete an item.':'No component recipe is listed in this dataset. The item may be purchased directly, dropped, or have missing recipe data.')+'</p>')+(incomplete||mismatch?'<p class="recipe-note">The source recipe is incomplete or its component costs differ from the listed item cost.</p>':'')+'<h3>BUILDS INTO</h3>'+(upgrades.length?'<div class="recipe-upgrades">'+upgrades.map(k=>recipeButton(k)).join('')+'</div>':'<p class="recipe-note">No upgrades listed in this dataset.</p>')+'</section>'}

let efficiencyMode=false;
const PERCENT_COLUMNS=new Set(['Spell Amp','Magic Resist','Status Resist','Slow Resist','Evasion']);
function efficiencyEligible(n){return n>=2&&!['category','combined'].includes(cols[n][1])}
function efficiencyValue(i,n){if(!efficiencyEligible(n)||!i.verified||!Number.isFinite(i.cost)||i.cost<=0)return null;let attrs=statAttributes(i,n);const name=cols[n][0];if(n>=2&&n<=4){if(i.attrib.some(a=>a.heading==='+$selected_attrib'))return null;attrs=attrs.concat(allAttributes(i))}if(!attrs.length)return null;
// These listed bonuses depend on break state, health, time or another condition.
const conditional={tranquil_boots:['Hp Regen','Move speed'],armlet:['STR'],vampire_fangs:['Hp Regen'],vambrace:['STR','AGI','INT'],power_treads:['STR','AGI','INT','Move speed']};
if(conditional[i.key]?.includes(name))return null;
if(attrs.some(a=>/aura|selected|primary|secondary|night|day|melee|ranged heroes/i.test(a.heading||'')))return null;
if(name==='Attack Range'&&attrs.some(a=>a.heading!=='+$attack_range_all'))return null;
if(attrs.some(a=>!/^[-+]?\d+(\.\d+)?$/.test(String(a.value).trim())))return null;
const percentages=attrs.map(a=>!!a.percentage);if(percentages.some(Boolean)&&!PERCENT_COLUMNS.has(name))return null;
if(PERCENT_COLUMNS.has(name)&&percentages.some(v=>!v))return null;
const values=attrs.map(signedValue);if(values.some(v=>v===null||v<0))return null;const bonus=values.reduce((s,v)=>s+v,0);if(bonus<=0)return null;const value=bonus/i.cost*1000;return Number.isFinite(value)?{value,unit:PERCENT_COLUMNS.has(name)?'pp /1k':'/1k'}:null}
function efficiencyText(e){return e.value.toLocaleString('en-GB',{minimumFractionDigits:1,maximumFractionDigits:2})+' '+e.unit}
function efficiencyCell(i,n){if(!efficiencyMode)return '';const e=efficiencyValue(i,n);return e?'<small class="efficiency-value">'+efficiencyText(e)+'</small>':''}
function sortedCompare(a,b){if(cols[sort][1]==='combined'){const x=calculateCombinedGoldEfficiency(a),y=calculateCombinedGoldEfficiency(b);if(x===null&&y===null)return a.dname.localeCompare(b.dname);if(x===null)return 1;if(y===null)return -1;return dir*(x-y)||a.dname.localeCompare(b.dname)}if(efficiencyMode&&efficiencyEligible(sort)){const x=efficiencyValue(a,sort),y=efficiencyValue(b,sort);if(!x&&!y)return a.dname.localeCompare(b.dname);if(!x)return 1;if(!y)return -1;return dir*(x.value-y.value)||a.dname.localeCompare(b.dname)}return dir*compare(a,b,sort)||a.dname.localeCompare(b.dname)}
function efficiencyHelp(){return '<div class="efficiency-help"><strong>Gold Efficiency</strong><p>Stat Bonus ÷ Gold Cost × 1,000. Higher values give more of this stat per 1,000 gold. Other stats, active abilities and strategic value are not included. Percentage stats use percentage points (pp). Conditional, alternative, aura and incompatible units are excluded.</p></div>'}

const REFERENCE_STAT_PRICES=Object.fromEntries([
['STR','gauntlets'],['AGI','slippers'],['INT','mantle'],['HP','vitality_booster'],['Mana','energy_booster'],['Hp Regen','ring_of_regen'],['Mana Regen','sobi_mask'],['Armor','chainmail'],['Damage','blades_of_attack'],['Attack Speed','gloves'],['Move speed','wind_lace'],['Magic Resist','cloak'],['Evasion','talisman_of_evasion']
].flatMap(([stat,key])=>{const item=items.find(i=>i.key===key),n=cols.findIndex(c=>c[0]===stat);if(!item||n<0)return [];const e=efficiencyValue(item,n);if(!e||e.value<=0)return [];const bonus=e.value*item.cost/1000;return [[stat,{statName:stat,referenceItem:item.dname,referenceItemKey:key,referenceGoldPrice:item.cost,statBonus:bonus,goldPerUnit:item.cost/bonus,unit:e.unit==='pp /1k'?'percentage point':stat.includes('Regen')?'per second':'point',sourceUrl:'https://www.dota2.com/datafeed/itemdata?language=english&item_id='+item.id,verificationDate:'2026-10-31'}]]}));
function combinedBreakdown(item){if(!item.verified||!Number.isFinite(item.cost)||item.cost<=0)return null;
// Do not present an upbeat partial score for a record with unvalued explicit penalties.
if((item.attrib||[]).some(a=>a.display&&(a.display.startsWith('-')||signedValue(a)<0)))return null;
const lines=[];for(const [name,ref]of Object.entries(REFERENCE_STAT_PRICES)){const n=cols.findIndex(c=>c[0]===name),e=efficiencyValue(item,n);if(!e)continue;const bonus=e.value*item.cost/1000;lines.push({stat:name,bonus,value:bonus*ref.goldPerUnit})}if(!lines.length)return null;const total=lines.reduce((sum,l)=>sum+l.value,0),percentage=total/item.cost*100;return Number.isFinite(percentage)&&percentage>0?{percentage,total,lines}:null}
function calculateCombinedGoldEfficiency(item){return combinedBreakdown(item)?.percentage??null}
function combinedCell(item){const result=combinedBreakdown(item);if(!result)return '<span class="zero">—</span>';const value=result.percentage,level=value>100?'above':value<80?'below':'neutral';return '<span class="combined-score '+level+'">'+value.toFixed(1)+'%</span><small class="combined-note">stat-only estimate</small>'}
function combinedHeader(n){const active=sort===n;return '<th aria-sort="'+(active?(dir<0?'descending':'ascending'):'none')+'"><div class="combined-heading"><button type="button" data-combined-info aria-haspopup="dialog">Combined Efficiency (%) ⓘ</button><button type="button" class="combined-sort" data-sort="'+n+'" aria-label="Sort combined efficiency '+(active&&dir<0?'lowest':'highest')+' first">'+(active?(dir<0?'↓':'↑'):'Sort')+'</button></div></th>'}
function openCombinedExplanation(){hideTip();const refs=Object.values(REFERENCE_STAT_PRICES);document.querySelector('#combined-body').innerHTML='<h2 id="combined-title">What is Combined Gold Efficiency?</h2><p>Compares the estimated gold value of an item’s measurable statistics against its purchase price. It is a theoretical stat-value comparison, not an overall measure of item strength.</p><h3>Formula</h3><p class="combined-formula">Efficiency = (Total Reference Stat Value / Item Price) × 100</p><h3>How reference values are calculated</h3><p>A basic item supplies a gold price per unit of a property. Each eligible bonus is multiplied by that reference price, and those values are added together and divided by the item’s purchase price.</p><p>Direct STR, AGI and INT are valued separately. An all-attribute bonus contributes once to each attribute; derived HP, mana, armor and attack speed are not added again.</p><h3>Worked example — hypothetical prices</h3><p>An item costs 2,000 gold and grants +200 HP, +5 armor and +20 attack speed.</p><table class="reference-table"><thead><tr><th>Property</th><th>Bonus</th><th>Gold/unit</th><th>Value</th></tr></thead><tbody><tr><td>HP</td><td>200</td><td>2</td><td>400</td></tr><tr><td>Armor</td><td>5</td><td>100</td><td>500</td></tr><tr><td>Attack Speed</td><td>20</td><td>25</td><td>500</td></tr><tr><td>Total</td><td></td><td></td><td>1,400</td></tr></tbody></table><p class="combined-formula">1,400 / 2,000 × 100 = 70%</p><p>These example prices are illustrative. The actual references used by this page are listed below.</p><h3>How to interpret the result</h3><ul><li><b>100%:</b> Measurable reference-stat value equals the price.</li><li><b>Above 100%:</b> Measurable reference-stat value exceeds the price.</li><li><b>Below 100%:</b> Measurable reference-stat value is below the price.</li></ul><p>An item below 100% may still be extremely valuable because of its abilities or situational usefulness. Colours show reference-stat valuation only, not purchase recommendations.</p><h3>Important limitations</h3><p>This model does not measure combat effectiveness, hero synergy, Blink or Dispel, stuns, team utility, timing, power spikes, inventory-slot value, interactions between stats, or strategic value.</p><p>Unpriced stats, actives, auras, conditional bonuses and incompatible units are excluded. Flat regeneration is separate from percentage regeneration. Items with explicit stat penalties are left unscored rather than assigning a misleading partial benefit. A dash means unavailable, not zero.</p><p>This is a stat-only theorycrafting estimate, not a universal item ranking.</p><details><summary>Actual reference prices · verified 31 October 2026</summary><div class="reference-scroll"><table class="reference-table"><thead><tr><th>Stat</th><th>Reference item</th><th>Cost</th><th>Bonus</th><th>Gold/unit</th></tr></thead><tbody>'+refs.map(r=>'<tr><td>'+esc(r.statName)+'<small>'+esc(r.unit)+'</small></td><td><a target="_blank" rel="noopener noreferrer" href="'+r.sourceUrl+'">'+esc(r.referenceItem)+'</a></td><td>'+r.referenceGoldPrice+'</td><td>'+Number(r.statBonus.toFixed(4))+'</td><td>'+r.goldPerUnit.toFixed(2)+'</td></tr>').join('')+'</tbody></table></div></details><p class="reference-date">References use the embedded Valve-feed snapshot verified 31 October 2026, not historical wiki prices. No patch number is inferred. Spell amplification, status/slow resistance, attack range and percentage regeneration are not assigned reference prices.</p><p><a href="https://dota2.fandom.com/wiki/Item_Gold_Efficiency" target="_blank" rel="noopener noreferrer">Read more: Dota 2 Wiki — Item Gold Efficiency ↗</a></p>';const modal=document.querySelector('#combined-modal');if(!modal.open)modal.showModal()}

function render(){updateStatsNavigation();document.querySelector('#stat-tooltip').hidden=true;const q=document.querySelector('#search').value.toLowerCase();let list=items.filter(i=>i.dname.toLowerCase().includes(q)&&(document.querySelector('#scope').value==='all'||i.shop)&&matchesTag(i,activeTagId));list.sort(sortedCompare);document.querySelector('#count').textContent=list.length+' items'+(activeTagId?' · '+(visibleTags().find(t=>t.id===activeTagId)?.label||activeTagId):'')+' · Sorted by: '+cols[sort][0]+(efficiencyMode&&efficiencyEligible(sort)?' Efficiency':'')+' '+(dir<0?'↓':'↑');document.querySelector('#head').innerHTML=cols.map((c,n)=>c[1]==='combined'?combinedHeader(n):'<th aria-sort="'+(n===sort?(dir<0?'descending':'ascending'):'none')+'"><button aria-describedby="stat-tooltip" aria-label="'+esc(c[0])+'" '+((c[1]||'').startsWith('hero_')?'aria-disabled="true" ':'')+'data-sort="'+n+'">'+(icons[c[0]]?'<img alt="" src="'+icons[c[0]]+'">':c[0])+((c[1]||'').startsWith('hero_')?'':n===sort?(dir<0?' ↓':' ↑'):'')+(efficiencyMode&&n===sort&&efficiencyEligible(n)?'<small class="efficiency-header">/1k gold</small>':'')+'</button></th>').join('');document.querySelector('#rows').innerHTML=list.map(i=>'<tr>'+cols.map((c,n)=>c[1]==='combined'?'<td class="combined-cell">'+combinedCell(i)+'</td>':n===0?'<td><button data-item="'+esc(i.key)+'"><img loading="lazy" alt="" src="https://cdn.cloudflare.steamstatic.com'+esc(i.img)+'">'+esc(i.dname)+'</button></td>':'<td class="'+(val(i,n)==null?'zero':String(val(i,n))==='Hero-dependent'?'dependent':'')+'">'+(val(i,n)==null?'—':esc(Array.isArray(val(i,n))?val(i,n).join(' / '):val(i,n)))+efficiencyCell(i,n)+'</td>').join('')+'</tr>').join('')||'<tr><td colspan="21">No verified matches in this view. Clear the tag or search, or choose All dataset items to include zero-cost items. Some effects have limited verified coverage.</td></tr>';}

const tooltip=document.querySelector('#stat-tooltip');
const header=document.querySelector('#head');let tipTimer,tipTarget;
const fullNames={STR:'Strength',AGI:'Agility',INT:'Intelligence','Status Resist':'Status Resistance','Slow Resist':'Slow Resistance','Magic Resist':'Magic Resistance',Damage:'Attack Damage','Move speed':'Movement Speed',Gold:'Gold Cost'};
function hideTip(){clearTimeout(tipTimer);tooltip.hidden=true;tipTarget=null}
function showTip(button){clearTimeout(tipTimer);tipTarget=button;const c=cols[+button.dataset.sort];tooltip.innerHTML='<strong>'+esc(fullNames[c[0]]||c[0])+'</strong><p>'+esc(descriptions[c[0]]||c[0])+'</p>'+(['Status Resist','Slow Resist'].includes(c[0])?'<a href="https://liquipedia.net/dota2/'+(c[0]==='Status Resist'?'Status_Resistance':'Slow_Resistance')+'" target="_blank" rel="noopener">Read mechanics on Liquipedia ↗</a>':'')+((c[1]||'').startsWith('hero_')?'':'<small>Click the column header to sort.</small>');if(efficiencyMode&&efficiencyEligible(+button.dataset.sort))tooltip.innerHTML+=efficiencyHelp();tooltip.hidden=false;const r=button.getBoundingClientRect(),t=tooltip.getBoundingClientRect();tooltip.style.left=Math.max(12,Math.min(r.left+r.width/2-t.width/2,window.innerWidth-t.width-12))+'px';tooltip.style.top=Math.max(12,r.bottom+t.height+10<window.innerHeight?r.bottom+10:r.top-t.height-10)+'px'}
function scheduleHide(){clearTimeout(tipTimer);tipTimer=setTimeout(hideTip,180)}
header.addEventListener('pointerover',e=>{const b=e.target.closest('[data-sort]');if(b)showTip(b)});
header.addEventListener('pointerout',e=>{if(!e.target.closest('[data-sort]')?.contains(e.relatedTarget))scheduleHide()});
header.addEventListener('focusin',e=>{const b=e.target.closest('[data-sort]');if(b)showTip(b)});
header.addEventListener('focusout',scheduleHide);
tooltip.addEventListener('pointerenter',()=>clearTimeout(tipTimer));tooltip.addEventListener('pointerleave',scheduleHide);tooltip.addEventListener('focusin',()=>clearTimeout(tipTimer));tooltip.addEventListener('focusout',scheduleHide);
document.addEventListener('keydown',e=>{if(e.key==='Escape')hideTip()});window.addEventListener('scroll',hideTip,true);window.addEventListener('resize',hideTip);
document.querySelector('#head').onclick=e=>{if(e.target.closest('[data-combined-info]')){openCombinedExplanation();return}const b=e.target.closest('[data-sort]');if(b){const n=+b.dataset.sort;if((cols[n][1]||'').startsWith('hero_'))return;dir=n===sort?-dir:(n===0||cols[n][1]==='category')?1:-1;sort=n;render()}};document.querySelector('#rows').onclick=e=>{const b=e.target.closest('[data-item]');if(b)openItem(b.dataset.item)};function openItem(key){statsFocusedItem=key;updateStatsNavigation();const i=DATA[key];if(!i)return;const abilities=i.abilities||[];const kinds=[...new Set(abilities.map(a=>a.type).filter(Boolean))];const kind=kinds.length?kinds.map(k=>k.charAt(0).toUpperCase()+k.slice(1)).join(' / '):'Passive';const statHtml=(i.attrib||[]).filter(a=>a.display).map(a=>{const value=Array.isArray(a.value)?a.value.join(' / '):a.value;return '<div>'+esc(a.display).replace('{value}','<strong>'+esc(value)+'</strong>')+'</div>'}).join('');document.querySelector('#content').innerHTML='<div class="item-top"><img alt="" src="https://cdn.cloudflare.steamstatic.com'+esc(i.img)+'"><div><h2>'+esc(i.dname)+'</h2><a class="item-tree-link" href="item-tree.html?'+esc(new URLSearchParams({item:key,...(activeTagId?{tag:activeTagId}:{}),...(document.querySelector('#scope').value==='all'?{scope:'all'}:{})}).toString())+'">Show item tree →</a><div class="item-cost">'+(i.cost>0?'<img alt="Gold" src="'+icons.Gold+'">'+Number(i.cost).toLocaleString():'No gold cost listed')+'</div></div></div><div class="item-kind">ABILITY: '+esc(kind)+'</div>'+(statHtml?'<div class="item-stats">'+statHtml+'</div>':'')+abilities.map(a=>'<section class="item-ability"><h3><span>'+esc(a.type? a.type.charAt(0).toUpperCase()+a.type.slice(1)+': ':'')+'</span>'+esc(a.title)+'</h3><p>'+esc(a.description).replace(/([0-9]+(?:[.][0-9]+)?%?)/g,'<strong>$1</strong>')+'</p></section>').join('')+((i.mc||i.cd)?'<div class="item-resources">'+(i.mc?'<span class="item-mana" title="Mana cost">◆ '+esc(Array.isArray(i.mc)?i.mc.join(' / '):i.mc)+'</span>':'')+(i.cd?'<span title="Cooldown">◷ '+esc(Array.isArray(i.cd)?i.cd.join(' / '):i.cd)+'s</span>':'')+'</div>':'')+(!i.verified?'<p class="recipe-note">Historical record: not verified against the current Valve feed.</p>':'')+(i.notes?'<details class="item-notes"><summary>MORE DETAILS</summary><p>'+esc(i.notes)+'</p></details>':'')+(i.lore?'<div class="item-lore">'+esc(i.lore)+'</div>':'')+recipeSection(key)+'<div class="item-footer">'+esc(i.category||'Recipe')+' · Esc to close</div>';const dialog=document.querySelector('#detail');if(!dialog.open)dialog.showModal();dialog.scrollTop=0};document.querySelector('#content').onclick=e=>{const b=e.target.closest('[data-recipe-item]');if(b)openItem(b.dataset.recipeItem)};document.querySelector('#close').onclick=()=>document.querySelector('#detail').close();document.querySelector('#search').oninput=render;document.querySelector('#scope').onchange=render;document.querySelector('#reset').onclick=()=>{activeTagId=null;sort=1;dir=-1;document.querySelector('#search').value='';document.querySelector('#scope').value='shop';renderTags();render()};render();

document.querySelector('#efficiency').onchange=e=>{efficiencyMode=e.target.checked;if(efficiencyMode&&efficiencyEligible(sort))dir=-1;document.querySelector('#efficiency-indicator').hidden=!efficiencyMode;hideTip();render()};
document.querySelector('#combined-close').onclick=()=>document.querySelector('#combined-modal').close();
