document.querySelector('.tag-mode').onclick=e=>{const b=e.target.closest('[data-mode]');if(b)setTagMode(b.dataset.mode)};
tagBar.onclick=e=>{const b=e.target.closest('[data-tag]');if(b)selectTag(b.dataset.tag)};
tagBar.addEventListener('pointerover',e=>{const b=e.target.closest('[data-tag]');if(b)showTagTip(b)});
