function updateStatsNavigation(){const p=new URLSearchParams();if(activeTagId)p.set('tag',activeTagId);if(statsFocusedItem)p.set('item',statsFocusedItem);if(document.querySelector('#scope').value==='all')p.set('scope','all');document.querySelector('#tree-link').href='item-tree.html'+(p.size?'?'+p:'')}
const incoming=new URLSearchParams(location.search);const incomingTag=incoming.get('tag'),incomingItem=incoming.get('item');if([...BASIC_TAGS,...ALL_TAGS].some(t=>t.id===incomingTag)){activeTagId=incomingTag;if(!BASIC_TAGS.some(t=>t.id===incomingTag))tagMode='advanced'}if(incoming.get('scope')==='all')document.querySelector('#scope').value='all';if(incomingItem&&DATA[incomingItem]){statsFocusedItem=incomingItem;if(!DATA[incomingItem].shop)document.querySelector('#scope').value='all';document.querySelector('#search').value=DATA[incomingItem].dname}renderTags();render();if(incomingItem&&DATA[incomingItem])openItem(incomingItem);
